\begin{proof}
It follows from \eqnok{eq:QV1} that
\begin{align*}
\tfrac{\partial V^\pi(s_0)}{\partial \pi(a|s)}
&= \tfrac{\partial}{\partial \pi(a'|s)} \tsum_{a'\in \cA} \pi(a'|s_0) Q^\pi(s_0, a')\\
&=  \tsum_{a' \in \cA} 
\left[
\tfrac{\partial \pi(a'|s_0)}{\partial \pi(a|s)} Q^\pi(s_0, a')
+ \pi(a'|s_0) 
\tfrac{\partial Q^\pi(s_0, a')}{\partial \pi(a|s)}
\right].
\end{align*}
Also the relation in \eqnok{eq:QV2}
implies that
\begin{align*}
\tfrac{\partial Q^\pi(s_0, a')}{\partial \pi(a|s)}
= \tfrac{  \partial h^\pi(s_0)}{\partial \pi (a|s)} +
\gamma \tsum_{s' \in \cS} 
\cP(s'| s_0, a') \tfrac{\partial V^\pi(s')}{\partial \pi(a|s)}.
\end{align*}
Combining the above two relations, we obtain
\begin{align*}
\tfrac{\partial V^\pi(s_0)}{\partial \pi(a|s)}
&= \tsum_{a' \in \cA} \left[ \tfrac{\partial \pi(a'|s_0)}{\partial \pi(a|s)} Q^\pi(s_0, a')
+ \pi(a'|s_0)  \tfrac{  \partial h^\pi(s_0)}{\partial \pi (a|s)}\right]  \\
& \quad + \gamma \tsum_{a' \in \cA} \pi(a'|s_0) \tsum_{s' \in \cS} 
\cP(s'| s_0, a') \tfrac{\partial V^\pi(s')}{\partial \pi(a|s)} \\
&=\tsum_{x\in \cS} \tsum_{t=0}^\infty \gamma^t \Pr^\pi(s_t = x | s_0) \\
&\quad \quad  \tsum_{a' \in \cA} \left[ \tfrac{\partial \pi(a'|x)}{\partial \pi(a|s)} Q^\pi(x, a')
+ \pi(a'|x)  \tfrac{   \partial h^\pi(x)}{\partial \pi (a|s)}\right]\\
&=\tfrac{1}{1-\gamma} \tsum_{x\in \cS} d_{s_0}^\pi(x) \left\{
\tsum_{a' \in \cA} \left[ \tfrac{\partial \pi(a'|x)}{\partial \pi(a|s)} Q^\pi(x, a')\right]
+ \tfrac{   \partial h^\pi(x)}{\partial \pi (a|s)}\right\}\\
&= \tfrac{1}{1-\gamma} d_{s_0}^\pi(s) \left[ Q^\pi(s, a) + \tfrac{   \partial h^\pi(s)}{\partial \pi (a|s)}\right],
\end{align*}
where the second equality follows by
expanding $\tfrac{\partial V^\pi(s')}{\partial \pi(a|s)}$ recursively,
and the third equality follows from the definition of $d_{s_0}^\pi(s)$
in \eqnok{eq:def_visitation}, and the last identity follows from $\tfrac{\partial \pi(a'|x)}{\partial \pi(a|s)} =0$
for $x \neq s$ or $a' \neq a$, and $\tfrac{\partial h^\pi(x)}{\partial \pi (a|s)} =0$
for $x \neq s$.
\end{proof}

\begin{lemma} \label{prop_strong_monotone}
The VI problem in \eqnok{eq:VI_MDP} satisfies
\begin{align}
&\bbe_{s\sim \nu^*}
\left[
 \langle Q^{\pi}(s, \cdot),  \pi(\cdot|s) - \pi^*(\cdot | s)\rangle + h^\pi(s) - h^{\pi^*}(s)
\right] \nn \\
& \quad \quad =
 \bbe_{s\sim \nu^*}[(1- \gamma)(V^{\pi}(s) - V^{\pi^*}(s) ) ].
\end{align}
\end{lemma}

\begin{proof}
It follows from Lemma~\ref{lemma_per_diff} (with $\pi' = \pi^*$) that
\begin{align*}
(1- \gamma) [V^{\pi^*}(s) - V^{\pi}(s)] 
=\bbe_{s' \sim d_s^{\pi^*}}
\left[
\langle A^{\pi}(s', \cdot), \pi^*(\cdot | s')\rangle
+ h^{\pi^*}(s') - h^{\pi}(s')
\right].
\end{align*}
Let $e$ denote the vector of all $1$'s. Then, we have 
\begin{align}
\langle A^{\pi}(s', \cdot), \pi^*(\cdot | s')\rangle
&= \langle Q^{\pi}(s', \cdot) - V^\pi(s') e, \pi^*(\cdot | s')\rangle \nn\\
&= \langle Q^{\pi}(s', \cdot), \pi^*(\cdot | s')\rangle - V^\pi(s') \nn \\
&=  \langle Q^{\pi}(s', \cdot), \pi^*(\cdot | s')\rangle - \langle Q^{\pi}(s', \cdot), \pi(\cdot|s') \nn \\
&= \langle Q^{\pi}(s', \cdot), \pi^*(\cdot | s') - \pi(\cdot|s')\rangle, \label{eq:inner_product_equivalence}
\end{align}
where the first identity follows from the definition of $A^{\pi}(s', \cdot)$ in \eqnok{eq:def_advantage},
the second equality follows from the fact that $\langle e,  \pi^*(\cdot | s')\rangle = 1$,
and the third equality follows from the definition of $V^\pi$ in \eqnok{eq:def_V_function}.
Combining the above two relations and taking expectation w.r.t. $\nu^*$, we obtain
\begin{align*}
&(1- \gamma) \bbe_{s\sim \nu^*}[V^{\pi^*}(s) - V^{\pi}(s)] \\
&= \bbe_{s\sim \nu^*, s' \sim d_s^{\pi^*}}
\left[
 \langle Q^{\pi}(s', \cdot), \pi^*(\cdot | s') - \pi(\cdot|s')\rangle
 +   h^{\pi^*}(s') - h^{\pi}(s')
\right]\\
&= \bbe_{s\sim \nu^*}
\left[
 \langle Q^{\pi}(s, \cdot), \pi^*(\cdot | s) - \pi(\cdot|s)\rangle
 +   h^{\pi^*}(s) - h^{\pi}(s)
\right],
\end{align*}
where the second identity follows similarly to \eqnok{eq:stationary_relation}
since $\nu^*$ is the steady state distribution induced by $\pi^*$.
The result then follows by rearranging the terms.
\end{proof}

\begin{lemma} \label{lemma:prox_optimality}
For any $p(\cdot|s) \in \Delta_{|\cA|}$,
we have
\begin{align*}
&\eta_k[ \langle Q^{\pi_k}(s, \cdot), \pi_{k+1}(\cdot|s) - p(\cdot|s) \rangle + h^{\pi_{k+1}}(s) - h^{p}(s)]
+ D_{\pi_k}^{\pi_{k+1}}(s)\\
& \le D_{\pi_k}^p(s) -  (1 + \eta_k \mu) D_{\pi_{k+1}}^p(s).
\end{align*}
\end{lemma}

\begin{lemma} \label{prop:PMD_generic}
For any $s \in \cS$, we have
\begin{align}
V^{\pi_{k+1}}(s) &\le V^{\pi_k}(s), \label{eq:pmd_decrease1}\\
\langle Q^{\pi_k}(s, \cdot),\, \pi_{k+1}(\cdot | s) - \pi_k(\cdot|s) \rangle + h^{\pi_{k+1}}(s) - h^{\pi_{k}}(s)  
&\ge V^{\pi_{k+1}}(s) - V^{\pi_k}(s). \label{eq:pmd_decrease2}
\end{align}
\end{lemma}

\begin{proof}
It follows from Lemma~\ref{lemma_per_diff} (with $\pi' = \pi_{k+1}$, $\pi = \pi_k$ and $\tau = \tau_k$) that
\begin{align}
&V^{\pi_{k+1}}(s) - V^{\pi_k}(s) \nn\\
&=
\tfrac{1}{1-\gamma} \bbe_{s' \sim d_s^{\pi_{k+1}}}
\left[
\langle A^{\pi_k}(s', \cdot), \pi_{k+1}(\cdot | s')\rangle
+ h^{\pi_{k+1}}(s') - h^{\pi_k}(s')
\right]. \label{eq:perf_diff_pmd}
\end{align}
Similarly to \eqnok{eq:inner_product_equivalence}, we can show that
\begin{align*}
\langle A^{\pi_k}(s', \cdot), \pi_{k+1}(\cdot | s')\rangle
&= \langle Q^{\pi_k}(s', \cdot) - V^{\pi_k}(s') e, \pi_{k+1}(\cdot | s')\rangle\\
&= \langle Q^{\pi_k}(s', \cdot), \pi_{k+1}(\cdot | s')\rangle - V^{\pi_k}_{\tau_k}(s')\\
&= \langle Q^{\pi_k}(s', \cdot), \pi_{k+1}(\cdot | s') - \pi_k(\cdot| s')\rangle.
\end{align*}
Combining the above two identities, we then obtain
\begin{align}
V^{\pi_{k+1}}(s) - V^{\pi_k}(s) &=
\tfrac{1}{1-\gamma} \bbe_{s' \sim d_s^{\pi_{k+1}}}
\left[
\langle Q^{\pi_k}(s', \cdot), \pi_{k+1}(\cdot | s') - \pi_k(\cdot|s') \rangle \right.\nn \\
& \quad \quad \quad \quad \quad \quad \quad \quad
\left. + h^{\pi_{k+1}}(s') - h^{\pi_k}(s')\right]. \label{eq:improvement_in_one_step_temp}
\end{align}
Now we conclude from Lemma~\ref{lemma:prox_optimality} applied to \eqnok{eq:PMD_step}
with $p(\cdot|s') = \pi_k(\cdot|s')$ that
\begin{align}
& \langle Q^{\pi_{k}}(s', \cdot), 
\pi_{k+1}(\cdot|s') - \pi_k(\cdot|s') \rangle + h^{\pi_{k+1}}(s') - h^{\pi_k}(s') \nn \\
&\le  -\tfrac{1}{\eta_k} [(1+\eta_k \mu) D_{\pi_{k+1}}^{\pi_k}(s') + D_{\pi_k}^{\pi_{k+1}}(s')].\label{eq:negative_term_pmd}
\end{align}
The previous two conclusions
then clearly imply the result in \eqnok{eq:pmd_decrease1}.
It also follows from \eqnok{eq:negative_term_pmd} that
\begin{align}
&\bbe_{s' \sim d_s^{\pi_{k+1}}}
\left[
\langle Q^{\pi_k}(s', \cdot), \pi_{k+1}(\cdot | s') - \pi_k(\cdot|s') \rangle 
 + h^{\pi_{k+1}}(s') - h^{\pi_k}(s') \right]\nn \\
& \le d_s^{\pi_{k+1}}(s) \left[
\langle Q^{\pi_k}(s, \cdot), \pi_{k+1}(\cdot | s) - \pi_k(\cdot|s) \rangle 
 + h^{\pi_{k+1}}(s) - h^{\pi_k}(s) \right]\nn \\
 &\le (1-\gamma) \left[
\langle Q^{\pi_k}(s, \cdot), \pi_{k+1}(\cdot | s) - \pi_k(\cdot|s) \rangle 
 + h^{\pi_{k+1}}(s) - h^{\pi_k}(s) \right], \label{eq:negative_term_pmd_prob_switch}
\end{align}
where the last inequality follows from the fact that $d_s^{\pi_{k+1}}(s) \ge (1-\gamma)$ due to the definition of $d_s^{\pi_{k+1}}$
in \eqnok{eq:def_visitation}. The result in \eqnok{eq:pmd_decrease1} 
then follows immediately from \eqnok{eq:improvement_in_one_step_temp} and the above inequality.
\end{proof}

\begin{lemma} \label{lemma:induction_tech_sequence}
Assume that the nonnegative sequences $\{X_k\}_{k \ge 0}, \{Y_k\}_{k \ge 0}$ and $\{Z_k\}_{k \ge 0}$ satisfy
\beq \label{eq:induction_tech_sequence}
X_{k+1} \le \gamma X_{k} + (Y_k - Y_{k+1}) + Z_k. % \ \ \mbox{and} \ \ Y_k \ge Y_{k+1}.
\eeq
Let us denote $l = \left \lceil  \log_\gamma \tfrac{1}{4} \right \rceil$.
If $Y_k = Y \cdot 2^{-(\lfloor k/l \rfloor+1)}$ and $Z_k = Z \cdot 2^{-(\lfloor k/l \rfloor+2)}$ for some $Y\ge 0$ and $Z \ge 0$, 
then 
\beq  \label{eq:induction_tech_sequence_result}
X_k \le 2^{-\lfloor k/l \rfloor} (X_0 + Y + \tfrac{5Z}{4(1-\gamma)}).
\eeq
\end{lemma}

By using the assumptions in \eqnok{eq:expectation_ass} and \eqnok{eq:bias_ass} and
the decomposition 
\begin{align*}
 \langle \cQ^{\pi_{k},\xi_k}(s, \cdot), \pi_{k}(\cdot|s) - \pi^*(\cdot|s) \rangle
 &= \langle Q^{\pi_k}(s, \cdot),  \pi_{k}(\cdot|s) - \pi^*(\cdot|s) \rangle \\
 & \quad + \langle \bar \cQ^{\pi_k}(s, \cdot) - Q^{\pi_k}(s, \cdot),  \pi_{k}(\cdot|s) - \pi^*(\cdot|s) \rangle \\
 & \quad + \langle  \cQ^{\pi_k,\xi_k}(s, \cdot) - \bar \cQ^{\pi_k}(s, \cdot),  \pi_{k}(\cdot|s) - \pi^*(\cdot|s) \rangle,
\end{align*}
we can see that %Taking expectation w.r.t. $\xi_k$ conditional on $\xi_{\lceil \xi_{k-1} \rceil}$, 
\begin{align}
&\bbe_{\xi_k}[ \langle \cQ^{\pi_{k},\xi_k}(s, \cdot), \pi_{k}(\cdot|s) - \pi^*(\cdot|s) \rangle \mid \xi_{\lceil \xi_{k-1} \rceil}] \nn \\
&\ge  \langle Q^{\pi_k}(s, \cdot),  \pi_{k}(\cdot|s) - \pi^*(\cdot|s) \rangle - 2 \varsigma_k. \label{eq:bnd_bias_SPMD}
\end{align}

\begin{lemma} \label{prop:SPMD_generic}
For any $s \in \cS$, we have
\begin{align}
V^{\pi_{k+1}}(s) - V^{\pi_k}(s) &\le
\langle \cQ^{\pi_k,\xi_k}(s, \cdot) , \pi_{k+1}(\cdot | s) - \pi_k(\cdot|s) \rangle + h^{\pi_{k+1}}(s) - h^{\pi_{k}}(s) \nn\\
& \quad   +
\tfrac{1}{\eta_k} D_{\pi_k}^{\pi_{k+1}}(s)+ \tfrac{\eta_k \|\delta_k\|_\infty^2}{2(1-\gamma)}.
\label{eq:spmd_decrease2}
\end{align}
\end{lemma}

\begin{proof}
%We prove \eqnok{eq:spmd_decrease2} first since its proof is slightly more complicated.
Observe that \eqnok{eq:improvement_in_one_step_temp}
still holds, and hence that
\begin{align}
&V^{\pi_{k+1}}(s) - V^{\pi_k}(s)\nn \\
&=
\tfrac{1}{1-\gamma} \bbe_{s' \sim d_s^{\pi_{k+1}}}
\left[
\langle Q^{\pi_k}(s', \cdot), \pi_{k+1}(\cdot | s') - \pi_k(\cdot|s') \rangle + h^{\pi_{k+1}}(s') - h^{\pi_{k}}(s') \right] \nn \\
&=
\tfrac{1}{1-\gamma} \bbe_{s' \sim d_s^{\pi_{k+1}}}
\left[
\langle \cQ^{\pi_k,\xi_k}(s', \cdot), \pi_{k+1}(\cdot | s') - \pi_k(\cdot|s')\rangle + h^{\pi_{k+1}}(s') - h^{\pi_{k}}(s') \right.\nn \\
& \quad 
\left.  - \langle \delta_k, \pi_{k+1}(\cdot | s') - \pi_k(\cdot|s') \rangle \right] \nn\\
&\le \tfrac{1}{1-\gamma} \bbe_{s' \sim d_s^{\pi_{k+1}}}
\left[
\langle \cQ^{\pi_k,\xi_k}(s', \cdot), \pi_{k+1}(\cdot | s') - \pi_k(\cdot|s') \rangle + h^{\pi_{k+1}}(s') - h^{\pi_{k}}(s') \right.\nn \\
& \quad
\left. +
 \tfrac{1 }{2\eta_k}\|\pi_{k+1}(\cdot | s') - \pi_k(\cdot|s') \|_1^2 + \tfrac{\eta_k \|\delta_k\|_\infty^2}{2}  \right] \nn\\
 &\le \tfrac{1}{1-\gamma} \bbe_{s' \sim d_s^{\pi_{k+1}}}
\left[
\langle \cQ^{\pi_k,\xi_k}(s', \cdot), \pi_{k+1}(\cdot | s') - \pi_k(\cdot|s') \rangle + h^{\pi_{k+1}}(s') - h^{\pi_{k}}(s')\right.\nn \\
& \quad
\left. + \tfrac{1}{\eta_k} D_{\pi_{k}}^{\pi_{k+1}}(s') + \tfrac{\eta_k \|\delta_k\|_\infty^2}{2} \right], \label{eq:improvement_in_one_step_temp_stoch}
\end{align}
where the first inequality follows from Young's inequality and
the second one follows from the strong convexity of $D_{\pi_{k+1}}^{\pi_{k}}$ w.r.t. to $\|\cdot\|_1$.
Moreover, we conclude from Lemma~\ref{lemma:prox_optimality} 
applied to \eqnok{eq:SPMD_step}
with $Q^{\pi_{k}}$ replaced by $\cQ^{\pi_{k},\xi_k}$ and $p(\cdot|s') = \pi_k(\cdot|s')$ that
\begin{align*}
& \langle \cQ^{\pi_{k},\xi_k}(s', \cdot), 
\pi_{k+1}(\cdot|s') - \pi_k(\cdot|s') \rangle + h^{\pi_{k+1}}(s') - h^{\pi_{k}}(s') + \tfrac{1}{\eta_k} D_{\pi_k}^{\pi_{k+1}}(s')\\
&\le  -\tfrac{1}{\eta_k} [(1+ \eta_k \mu) D_{\pi_{k+1}}^{\pi_k}(s') ] \le 0,
\end{align*}
which implies that
\begin{align*}
&\bbe_{s' \sim d_s^{\pi_{k+1}}}
\left[
\langle \cQ^{\pi_k,\xi_k}(s', \cdot), \pi_{k+1}(\cdot | s') - \pi_k(\cdot|s') \rangle 
+ h^{\pi_{k+1}}(s') - h^{\pi_{k}}(s') +  \tfrac{1}{\eta_k} D_{\pi_{k+1}}^{\pi_{k}}(s') \right]\nn \\
& \le d_s^{\pi_{k+1}}(s) \left[
\langle \cQ^{\pi_k,\xi_k}(s, \cdot), \pi_{k+1}(\cdot | s) - \pi_k(\cdot|s) \rangle + h^{\pi_{k+1}}(s) - h^{\pi_{k}}(s) 
 + \tfrac{1}{\eta_k} D_{\pi_k}^{\pi_{k+1}}(s) \right]\nn \\
 &\le (1-\gamma) \left[
\langle \cQ^{\pi_k,\xi_k}(s, \cdot), \pi_{k+1}(\cdot | s) - \pi_k(\cdot|s) \rangle + h^{\pi_{k+1}}(s) - h^{\pi_{k}}(s) 
 + \tfrac{1}{\eta_k} D_{\pi_k}^{\pi_{k+1}}(s) \right], 
 \end{align*}
where the last inequality follows from the fact that $d_s^{\pi_{k+1}}(s) \ge 1-\gamma$ due to the definition of $d_s^{\pi_{k+1}}$
in \eqnok{eq:def_visitation}. The result in \eqnok{eq:spmd_decrease2} 
then follows immediately from \eqnok{eq:improvement_in_one_step_temp_stoch} and the above inequality.
\end{proof}

\begin{lemma} \label{prop:SPMD_regularized_MDPs}
For any $k \ge 0$, we have
\begin{align*}
&  \bbe_{\xi_{\lceil k \rceil}} [f(\pi_{k+1}) - f(\pi^*) + (\tfrac{1}{\eta_k}+  \mu) \cD(\pi_{k+1}, \pi^*)] \\
&\le   \bbe_{\xi_{\lceil k-1 \rceil}} [\gamma (f(\pi_k) - f(\pi^*))+ \tfrac{1}{\eta_k} \cD(\pi_k,\pi^*) ]
+ 2 \varsigma_k + \tfrac{ \eta_k \sigma_k^2}{2(1-\gamma)}.
\end{align*}
\end{lemma}

\begin{proof}
By Lemma~\ref{prop:SPMD_regularized_MDPs} and the selection of $\eta$, we have
\begin{align*}
& \bbe_{\xi_{\lceil k \rceil}} [f(\pi_{k+1}) - f(\pi^*) + \tfrac{\mu}{1-\gamma}  \cD(\pi_{k+1},\pi^*)] \\
&\le  \gamma [ \bbe_{\xi_{\lceil k-1 \rceil}} [f(\pi_k) - f(\pi^*) + \tfrac{\mu}{1-\gamma} \cD(\pi_k, \pi^*) ]
+ 2 \varsigma_k + \tfrac{ \sigma_k^2}{2 \gamma \mu},
\end{align*}
which, in view of Lemma~\ref{lemma:induction_tech_sequence}
with $X_k =  \bbe_{\xi_{\lceil k-1 \rceil}} [f(\pi_k) - f(\pi^*) + \tfrac{\mu}{1-\gamma} \cD(\pi_k, \pi^*)$
and $Z_k = 2 \varsigma_k + \tfrac{ \sigma_k^2}{2 \gamma \mu}$,
then implies that
\begin{align*}
&\bbe_{\xi_{\lceil k-1 \rceil}} [f(\pi_k) - f(\pi^*) + \tfrac{\mu}{1-\gamma} \cD(\pi_k, \pi^*)\\
&\le \gamma^{\lfloor k/l \rfloor}\left [f(\pi_0) - f(\pi^*) + \tfrac{\mu  \cD(\pi_0, \pi^*)}{1-\gamma}
+ \tfrac{5} {4}( \tfrac{2}{1-\gamma}+ \tfrac{ 1}{2 \gamma(1 -\gamma) \mu})\right]\\
&\le \gamma^{\lfloor k/l \rfloor}\left [f(\pi_0) - f(\pi^*) +\tfrac{1}{1-\gamma}( \mu  \log |\cA|
+ \tfrac{5} {2} + \tfrac{ 5}{8 \gamma \mu})\right].
\end{align*}
\end{proof}

