For a given policy $\pi$,
we measure its performance by the action-value
function ($Q$-function) $Q^\pi: \cS \times \cA \to \bbr$
defined as
\begin{align}
Q^\pi(s,a) &:=
\bbe\left[\tsum_{t=0}^\infty \gamma^t [c(s_t, a_t) + h^\pi(s_t)] \right. \nn \\
&\quad \quad\quad\quad \left. \mid s_0 = s, a_0 = a, a_t \sim \pi(\cdot | s_t), s_{t+1} \sim \cP(\cdot | s_t, a_t)\right]. \label{eq:def_Q_function}
\end{align}

It can be easily seen 
from the definitions of $Q^\pi$ and $V^\pi$ that
\begin{align}
V^\pi(s) &= \tsum_{a \in \cA} \pi( a | s) Q^\pi(s, a)  = \langle Q^\pi(s, \cdot),  \pi( \cdot | s) \rangle, \label{eq:QV1}  \\
Q^\pi(s, a) &= c(s, a) + h^\pi(s) + \gamma \tsum_{s' \in \cS} \cP(s'| s, a) V^\pi(s'). \label{eq:QV2}
\end{align}

By examining Bellman's optimality condition
for dynamic programming (\cite{BellmanDreyfus1959} and Chapter 6 of \cite{PutermanBook1994}), we can show the existence
of a policy $\pi^*$ which satisfies \eqnok{eq:opt_objective} simultaneously 
for all $s \in \cS$. Hence, we can formulate \eqnok{eq:opt_objective}
as an optimization problem with a single objective by taking the weighted sum of
$V^\pi$ over $s$ (with weights $\rho_s >0$ and $\tsum_{s \in S} \rho_s = 1$):
\beq \label{eq:opt_objective1}
\begin{array}{ll}
\min_\pi &  \bbe_{s \sim \rho} [V^{\pi}(s)] \\
\mbox{s.t.} & \pi(\cdot | s) \in \Delta_{|\cA|}, \forall s \in \cS.
\end{array}
\eeq

While the weights $\rho$ can be arbitrarily chosen, a reasonable selection
of $\rho$ would be the stationary state distribution
induced by the optimal policy $\pi^*$, denoted by $\nu^* \equiv \nu(\pi^*)$. As such,
problem~\eqnok{eq:opt_objective1} reduces to 
\beq \label{eq:MDP_OPT}
\begin{array}{ll}
\min_\pi & \left\{ f(\pi) := \bbe_{s \sim \nu^*} [V^{\pi}(s)] \right\}\\
\mbox{s.t.} & \pi(\cdot | s) \in \Delta_{|\cA|}, \forall s \in \cS.
\end{array}
\eeq

\beq\label{eq:VI_MDP}
\bbe_{s \sim \nu^*} \left[ \langle Q^{\pi^*}(s,\cdot), \pi(\cdot |s) - \pi^*(\cdot |s)\rangle + h^\pi(s) - h^{\pi^*}(s) \right]  \ge 0.
\eeq

\beq \label{eq:initial_p0}
 \pi_0(a | s) = 1/|\cA|, \ \forall a \in \cA, \forall s \in \cS.
 \eeq

\begin{algorithm}[H]
\caption{The policy mirror descent (PMD) method}
\begin{algorithmic}
\State {\bf Input:} initial points $\pi_0$ and stepsizes $\eta_k\ge 0$.
\For {$k =0,1,\ldots,$}
%\State  
\beq \label{eq:PMD_step}
\pi_{k+1}(\cdot|s) = \argmin_{p(\cdot|s) \in \Delta_{|\cA|}} \left\{ \eta_k[ \langle Q^{\pi_{k}}(s, \cdot), p(\cdot|s) \rangle + h^{p}(s)] + D_{\pi_k}^p(s)\right\},
\forall s \in \cS.
\eeq
\EndFor
\end{algorithmic} \label{basic_pmd}
\end{algorithm}

\beq \label{eq:def_distance_measure}
\cD (\pi_k, \pi^*) := \bbe_{s\sim \nu^*} [D_{\pi_{k}}^{\pi^*}(s)].
\eeq

In this subsection, we assume that for a given policy $\pi_k$,
there exists a stochastic estimator $\cQ^{\pi_k,\xi_k}$ s.t.
\begin{align}
 \bbe_{\xi_k} [\cQ^{\pi_k,\xi_k}] &= \bar \cQ^{\pi_k}, \label{eq:expectation_ass} \\
\bbe_{\xi_k}[\|\cQ^{\pi_k,\xi_k} - Q^{\pi_k} \|_\infty^2] &\le \sigma_k^2, \label{eq:variance_ass}\\
\|\bar \cQ^{\pi_k} - Q^{\pi_k}\|_\infty &\le \varsigma_k, \label{eq:bias_ass}
\end{align}

The stochastic policy mirror descent (SPMD)
is obtained by replacing $Q^{\pi_k}$ in \eqnok{eq:PMD_step} 
with its stochastic estimator $\cQ^{\pi_k,\xi_k}$, i.e.,
\beq \label{eq:SPMD_step}
\pi_{k+1}(\cdot|s) = \argmin_{p(\cdot|s) \in \Delta_{|\cA|}} \left\{ \Phi_k(p):=\eta_k [\langle \cQ^{\pi_{k},\xi_k}(s, \cdot), p(\cdot|s) \rangle + h^p(s)]+ D_{\pi_k}^p(s)\right\}.
\eeq

\beq \label{eq:def_SPMD_delta}
\delta_k := \cQ^{\pi_k,\xi_k} - Q^{\pi_k}.
\eeq

\begin{proof}
It follows from \eqnok{eq:QV1} that
\begin{align*}
\tfrac{\partial V^\pi(s_0)}{\partial \pi(a|s)}
&= \tfrac{\partial}{\partial \pi(a'|s)} \tsum_{a'\in \cA} \pi(a'|s_0) Q^\pi(s_0, a')\\
&=  \tsum_{a' \in \cA} 
\left[
\tfrac{\partial \pi(a'|s_0)}{\partial \pi(a|s)} Q^\pi(s_0, a')
+ \pi(a'|s_0) 
\tfrac{\partial Q^\pi(s_0, a')}{\partial \pi(a|s)}
\right].
\end{align*}
Also the relation in \eqnok{eq:QV2}
implies that
\begin{align*}
\tfrac{\partial Q^\pi(s_0, a')}{\partial \pi(a|s)}
= \tfrac{  \partial h^\pi(s_0)}{\partial \pi (a|s)} +
\gamma \tsum_{s' \in \cS} 
\cP(s'| s_0, a') \tfrac{\partial V^\pi(s')}{\partial \pi(a|s)}.
\end{align*}
Combining the above two relations, we obtain
\begin{align*}
\tfrac{\partial V^\pi(s_0)}{\partial \pi(a|s)}
&= \tsum_{a' \in \cA} \left[ \tfrac{\partial \pi(a'|s_0)}{\partial \pi(a|s)} Q^\pi(s_0, a')
+ \pi(a'|s_0)  \tfrac{  \partial h^\pi(s_0)}{\partial \pi (a|s)}\right]  \\
& \quad + \gamma \tsum_{a' \in \cA} \pi(a'|s_0) \tsum_{s' \in \cS} 
\cP(s'| s_0, a') \tfrac{\partial V^\pi(s')}{\partial \pi(a|s)} \\
&=\tsum_{x\in \cS} \tsum_{t=0}^\infty \gamma^t \Pr^\pi(s_t = x | s_0) \\
&\quad \quad  \tsum_{a' \in \cA} \left[ \tfrac{\partial \pi(a'|x)}{\partial \pi(a|s)} Q^\pi(x, a')
+ \pi(a'|x)  \tfrac{   \partial h^\pi(x)}{\partial \pi (a|s)}\right]\\
&=\tfrac{1}{1-\gamma} \tsum_{x\in \cS} d_{s_0}^\pi(x) \left\{
\tsum_{a' \in \cA} \left[ \tfrac{\partial \pi(a'|x)}{\partial \pi(a|s)} Q^\pi(x, a')\right]
+ \tfrac{   \partial h^\pi(x)}{\partial \pi (a|s)}\right\}\\
&= \tfrac{1}{1-\gamma} d_{s_0}^\pi(s) \left[ Q^\pi(s, a) + \tfrac{   \partial h^\pi(s)}{\partial \pi (a|s)}\right],
\end{align*}
where the second equality follows by
expanding $\tfrac{\partial V^\pi(s')}{\partial \pi(a|s)}$ recursively,
and the third equality follows from the definition of $d_{s_0}^\pi(s)$
in \eqnok{eq:def_visitation}, and the last identity follows from $\tfrac{\partial \pi(a'|x)}{\partial \pi(a|s)} =0$
for $x \neq s$ or $a' \neq a$, and $\tfrac{\partial h^\pi(x)}{\partial \pi (a|s)} =0$
for $x \neq s$.
\end{proof}

