\begin{lemma} \label{prop_strong_monotone}
The VI problem in \eqnok{eq:VI_MDP} satisfies
\begin{align}
&\bbe_{s\sim \nu^*}
\left[
 \langle Q^{\pi}(s, \cdot),  \pi(\cdot|s) - \pi^*(\cdot | s)\rangle + h^\pi(s) - h^{\pi^*}(s)
\right] \nn \\
& \quad \quad =
 \bbe_{s\sim \nu^*}[(1- \gamma)(V^{\pi}(s) - V^{\pi^*}(s) ) ].
\end{align}
\end{lemma}

\begin{proof}
It follows from Lemma~\ref{lemma_per_diff} (with $\pi' = \pi^*$) that
\begin{align*}
(1- \gamma) [V^{\pi^*}(s) - V^{\pi}(s)] 
=\bbe_{s' \sim d_s^{\pi^*}}
\left[
\langle A^{\pi}(s', \cdot), \pi^*(\cdot | s')\rangle
+ h^{\pi^*}(s') - h^{\pi}(s')
\right].
\end{align*}
Let $e$ denote the vector of all $1$'s. Then, we have 
\begin{align}
\langle A^{\pi}(s', \cdot), \pi^*(\cdot | s')\rangle
&= \langle Q^{\pi}(s', \cdot) - V^\pi(s') e, \pi^*(\cdot | s')\rangle \nn\\
&= \langle Q^{\pi}(s', \cdot), \pi^*(\cdot | s')\rangle - V^\pi(s') \nn \\
&=  \langle Q^{\pi}(s', \cdot), \pi^*(\cdot | s')\rangle - \langle Q^{\pi}(s', \cdot), \pi(\cdot|s') \nn \\
&= \langle Q^{\pi}(s', \cdot), \pi^*(\cdot | s') - \pi(\cdot|s')\rangle, \label{eq:inner_product_equivalence}
\end{align}
where the first identity follows from the definition of $A^{\pi}(s', \cdot)$ in \eqnok{eq:def_advantage},
the second equality follows from the fact that $\langle e,  \pi^*(\cdot | s')\rangle = 1$,
and the third equality follows from the definition of $V^\pi$ in \eqnok{eq:def_V_function}.
Combining the above two relations and taking expectation w.r.t. $\nu^*$, we obtain
\begin{align*}
&(1- \gamma) \bbe_{s\sim \nu^*}[V^{\pi^*}(s) - V^{\pi}(s)] \\
&= \bbe_{s\sim \nu^*, s' \sim d_s^{\pi^*}}
\left[
 \langle Q^{\pi}(s', \cdot), \pi^*(\cdot | s') - \pi(\cdot|s')\rangle
 +   h^{\pi^*}(s') - h^{\pi}(s')
\right]\\
&= \bbe_{s\sim \nu^*}
\left[
 \langle Q^{\pi}(s, \cdot), \pi^*(\cdot | s) - \pi(\cdot|s)\rangle
 +   h^{\pi^*}(s) - h^{\pi}(s)
\right],
\end{align*}
where the second identity follows similarly to \eqnok{eq:stationary_relation}
since $\nu^*$ is the steady state distribution induced by $\pi^*$.
The result then follows by rearranging the terms.
\end{proof}

