&(1- \gamma) \bbe_{s\sim \nu^*}[V^{\pi^*}(s) - V^{\pi}(s)] \\
&= \bbe_{s\sim \nu^*, s' \sim d_s^{\pi^*}}
\left[
 \langle Q^{\pi}(s', \cdot), \pi^*(\cdot | s') - \pi(\cdot|s')\rangle
 +   h^{\pi^*}(s') - h^{\pi}(s')
\right]\\
&= \bbe_{s\sim \nu^*}
\left[
 \langle Q^{\pi}(s, \cdot), \pi^*(\cdot | s) - \pi(\cdot|s)\rangle
 +   h^{\pi^*}(s) - h^{\pi}(s)
\right],
\end{align*}
where the second identity follows similarly to \eqnok{eq:stationary_relation}
since $\nu^*$ is the steady state distribution induced by $\pi^*$.
The result then follows by rearranging the terms.
\end{proof}

\begin{lemma} \label{lemma:prox_optimality}
For any $p(\cdot|s) \in \Delta_{|\cA|}$,
we have
\begin{align*}
&\eta_k[ \langle Q^{\pi_k}(s, \cdot), \pi_{k+1}(\cdot|s) - p(\cdot|s) \rangle + h^{\pi_{k+1}}(s) - h^{p}(s)]
+ D_{\pi_k}^{\pi_{k+1}}(s)\\
& \le D_{\pi_k}^p(s) -  (1 + \eta_k \mu) D_{\pi_{k+1}}^p(s).
\end{align*}
\end{lemma}

\begin{lemma} \label{prop:PMD_generic}
For any $s \in \cS$, we have
\begin{align}
V^{\pi_{k+1}}(s) &\le V^{\pi_k}(s), \label{eq:pmd_decrease1}\\
\langle Q^{\pi_k}(s, \cdot),\, \pi_{k+1}(\cdot | s) - \pi_k(\cdot|s) \rangle + h^{\pi_{k+1}}(s) - h^{\pi_{k}}(s)  
&\ge V^{\pi_{k+1}}(s) - V^{\pi_k}(s). \label{eq:pmd_decrease2}
\end{align}
\end{lemma}

\begin{proof}
It follows from Lemma~\ref{lemma_per_diff} (with $\pi' = \pi_{k+1}$, $\pi = \pi_k$ and $\tau = \tau_k$) that
\begin{align}
&V^{\pi_{k+1}}(s) - V^{\pi_k}(s) \nn\\
&=
\tfrac{1}{1-\gamma} \bbe_{s' \sim d_s^{\pi_{k+1}}}
\left[
\langle A^{\pi_k}(s', \cdot), \pi_{k+1}(\cdot | s')\rangle
+ h^{\pi_{k+1}}(s') - h^{\pi_k}(s')
\right]. \label{eq:perf_diff_pmd}
\end{align}
Similarly to \eqnok{eq:inner_product_equivalence}, we can show that
\begin{align*}
\langle A^{\pi_k}(s', \cdot), \pi_{k+1}(\cdot | s')\rangle
&= \langle Q^{\pi_k}(s', \cdot) - V^{\pi_k}(s') e, \pi_{k+1}(\cdot | s')\rangle\\
&= \langle Q^{\pi_k}(s', \cdot), \pi_{k+1}(\cdot | s')\rangle - V^{\pi_k}_{\tau_k}(s')\\
&= \langle Q^{\pi_k}(s', \cdot), \pi_{k+1}(\cdot | s') - \pi_k(\cdot| s')\rangle.
\end{align*}
Combining the above two identities, we then obtain
\begin{align}
V^{\pi_{k+1}}(s) - V^{\pi_k}(s) &=
\tfrac{1}{1-\gamma} \bbe_{s' \sim d_s^{\pi_{k+1}}}
\left[
\langle Q^{\pi_k}(s', \cdot), \pi_{k+1}(\cdot | s') - \pi_k(\cdot|s') \rangle \right.\nn \\
& \quad \quad \quad \quad \quad \quad \quad \quad
\left. + h^{\pi_{k+1}}(s') - h^{\pi_k}(s')\right]. \label{eq:improvement_in_one_step_temp}
\end{align}
Now we conclude from Lemma~\ref{lemma:prox_optimality} applied to \eqnok{eq:PMD_step}
with $p(\cdot|s') = \pi_k(\cdot|s')$ that
\begin{align}
& \langle Q^{\pi_{k}}(s', \cdot), 
\pi_{k+1}(\cdot|s') - \pi_k(\cdot|s') \rangle + h^{\pi_{k+1}}(s') - h^{\pi_k}(s') \nn \\
&\le  -\tfrac{1}{\eta_k} [(1+\eta_k \mu) D_{\pi_{k+1}}^{\pi_k}(s') + D_{\pi_k}^{\pi_{k+1}}(s')].\label{eq:negative_term_pmd}
\end{align}
The previous two conclusions
then clearly imply the result in \eqnok{eq:pmd_decrease1}.
It also follows from \eqnok{eq:negative_term_pmd} that
\begin{align}
&\bbe_{s' \sim d_s^{\pi_{k+1}}}
\left[
\langle Q^{\pi_k}(s', \cdot), \pi_{k+1}(\cdot | s') - \pi_k(\cdot|s') \rangle 
 + h^{\pi_{k+1}}(s') - h^{\pi_k}(s') \right]\nn \\
& \le d_s^{\pi_{k+1}}(s) \left[
\langle Q^{\pi_k}(s, \cdot), \pi_{k+1}(\cdot | s) - \pi_k(\cdot|s) \rangle 
 + h^{\pi_{k+1}}(s) - h^{\pi_k}(s) \right]\nn \\
 &\le (1-\gamma) \left[
\langle Q^{\pi_k}(s, \cdot), \pi_{k+1}(\cdot | s) - \pi_k(\cdot|s) \rangle 
 + h^{\pi_{k+1}}(s) - h^{\pi_k}(s) \right], \label{eq:negative_term_pmd_prob_switch}
\end{align}
where the last inequality follows from the fact that $d_s^{\pi_{k+1}}(s) \ge (1-\gamma)$ due to the definition of $d_s^{\pi_{k+1}}$
in \eqnok{eq:def_visitation}. The result in \eqnok{eq:pmd_decrease1} 
then follows immediately from \eqnok{eq:improvement_in_one_step_temp} and the above inequality.
\end{proof}

