\begin{lemma} \label{prop:SPMD_generic}
For any $s \in \cS$, we have
\begin{align}
V^{\pi_{k+1}}(s) - V^{\pi_k}(s) &\le
\langle \cQ^{\pi_k,\xi_k}(s, \cdot) , \pi_{k+1}(\cdot | s) - \pi_k(\cdot|s) \rangle + h^{\pi_{k+1}}(s) - h^{\pi_{k}}(s) \nn\\
& \quad   +
\tfrac{1}{\eta_k} D_{\pi_k}^{\pi_{k+1}}(s)+ \tfrac{\eta_k \|\delta_k\|_\infty^2}{2(1-\gamma)}.
\label{eq:spmd_decrease2}
\end{align}
\end{lemma}

\begin{proof}
%We prove \eqnok{eq:spmd_decrease2} first since its proof is slightly more complicated.
Observe that \eqnok{eq:improvement_in_one_step_temp}
still holds, and hence that
\begin{align}
&V^{\pi_{k+1}}(s) - V^{\pi_k}(s)\nn \\
&=
\tfrac{1}{1-\gamma} \bbe_{s' \sim d_s^{\pi_{k+1}}}
\left[
\langle Q^{\pi_k}(s', \cdot), \pi_{k+1}(\cdot | s') - \pi_k(\cdot|s') \rangle + h^{\pi_{k+1}}(s') - h^{\pi_{k}}(s') \right] \nn \\
&=
\tfrac{1}{1-\gamma} \bbe_{s' \sim d_s^{\pi_{k+1}}}
\left[
\langle \cQ^{\pi_k,\xi_k}(s', \cdot), \pi_{k+1}(\cdot | s') - \pi_k(\cdot|s')\rangle + h^{\pi_{k+1}}(s') - h^{\pi_{k}}(s') \right.\nn \\
& \quad 
\left.  - \langle \delta_k, \pi_{k+1}(\cdot | s') - \pi_k(\cdot|s') \rangle \right] \nn\\
&\le \tfrac{1}{1-\gamma} \bbe_{s' \sim d_s^{\pi_{k+1}}}
\left[
\langle \cQ^{\pi_k,\xi_k}(s', \cdot), \pi_{k+1}(\cdot | s') - \pi_k(\cdot|s') \rangle + h^{\pi_{k+1}}(s') - h^{\pi_{k}}(s') \right.\nn \\
& \quad
\left. +
 \tfrac{1 }{2\eta_k}\|\pi_{k+1}(\cdot | s') - \pi_k(\cdot|s') \|_1^2 + \tfrac{\eta_k \|\delta_k\|_\infty^2}{2}  \right] \nn\\
 &\le \tfrac{1}{1-\gamma} \bbe_{s' \sim d_s^{\pi_{k+1}}}
\left[
\langle \cQ^{\pi_k,\xi_k}(s', \cdot), \pi_{k+1}(\cdot | s') - \pi_k(\cdot|s') \rangle + h^{\pi_{k+1}}(s') - h^{\pi_{k}}(s')\right.\nn \\
& \quad
\left. + \tfrac{1}{\eta_k} D_{\pi_{k}}^{\pi_{k+1}}(s') + \tfrac{\eta_k \|\delta_k\|_\infty^2}{2} \right], \label{eq:improvement_in_one_step_temp_stoch}
\end{align}
where the first inequality follows from Young's inequality and
the second one follows from the strong convexity of $D_{\pi_{k+1}}^{\pi_{k}}$ w.r.t. to $\|\cdot\|_1$.
Moreover, we conclude from Lemma~\ref{lemma:prox_optimality} 
applied to \eqnok{eq:SPMD_step}
with $Q^{\pi_{k}}$ replaced by $\cQ^{\pi_{k},\xi_k}$ and $p(\cdot|s') = \pi_k(\cdot|s')$ that
\begin{align*}
& \langle \cQ^{\pi_{k},\xi_k}(s', \cdot), 
\pi_{k+1}(\cdot|s') - \pi_k(\cdot|s') \rangle + h^{\pi_{k+1}}(s') - h^{\pi_{k}}(s') + \tfrac{1}{\eta_k} D_{\pi_k}^{\pi_{k+1}}(s')\\
&\le  -\tfrac{1}{\eta_k} [(1+ \eta_k \mu) D_{\pi_{k+1}}^{\pi_k}(s') ] \le 0,
\end{align*}
which implies that
\begin{align*}
&\bbe_{s' \sim d_s^{\pi_{k+1}}}
\left[
\langle \cQ^{\pi_k,\xi_k}(s', \cdot), \pi_{k+1}(\cdot | s') - \pi_k(\cdot|s') \rangle 
+ h^{\pi_{k+1}}(s') - h^{\pi_{k}}(s') +  \tfrac{1}{\eta_k} D_{\pi_{k+1}}^{\pi_{k}}(s') \right]\nn \\
& \le d_s^{\pi_{k+1}}(s) \left[
\langle \cQ^{\pi_k,\xi_k}(s, \cdot), \pi_{k+1}(\cdot | s) - \pi_k(\cdot|s) \rangle + h^{\pi_{k+1}}(s) - h^{\pi_{k}}(s) 
 + \tfrac{1}{\eta_k} D_{\pi_k}^{\pi_{k+1}}(s) \right]\nn \\
 &\le (1-\gamma) \left[
\langle \cQ^{\pi_k,\xi_k}(s, \cdot), \pi_{k+1}(\cdot | s) - \pi_k(\cdot|s) \rangle + h^{\pi_{k+1}}(s) - h^{\pi_{k}}(s) 
 + \tfrac{1}{\eta_k} D_{\pi_k}^{\pi_{k+1}}(s) \right], 
 \end{align*}
where the last inequality follows from the fact that $d_s^{\pi_{k+1}}(s) \ge 1-\gamma$ due to the definition of $d_s^{\pi_{k+1}}$
in \eqnok{eq:def_visitation}. The result in \eqnok{eq:spmd_decrease2} 
then follows immediately from \eqnok{eq:improvement_in_one_step_temp_stoch} and the above inequality.
\end{proof}

